import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int k = Math.min(n, 10);
        int slots = 1;
        for (int i = 0; i < k; i++) {
            slots = slots * 2;
        }
        System.out.println(slots - 1);
    }
}

